        AND o.reporter_id = #{reporterId}


        AND o.status = #{q.status}


        AND o.priority = #{q.priority}


        AND d.room_name = #{q.roomName}


        AND (o.order_no LIKE CONCAT('%', #{q.keyword}, '%')
